window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-25c6b4fabf7e339d"]={"versions": [{"id": "FIG-25c6b4fabf7e339d", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd EthTSyn_TimesyncSequence</code>) zur Zeitsynchronisation über Ethernet (Time Synchronization Sequence) in der AUTOSAR Classic Platform. Das Diagramm spezifiziert den Interaktionsablauf zwischen den BSW-Modulen Synchronized Time-Base Manager (<code>StbM</code>) und Ethernet Time Synchronization (<code>EthTSyn</code>) jeweils auf Master- und Slave-Seite.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Lebenslinien (Instanzen / Module mit Stereotyp «module»):</p>\n<ul class=\"fig-list\"><li><code>StbM (Time Slave): StbM</code>\n</li><li><code>EthTSyn (Time Slave): EthTSyn</code>\n</li><li><code>EthTSyn (Time Master): EthTSyn</code>\n</li><li><code>StbM (Time Master): StbM</code>\n</li></ul>\n<p class=\"fig-p\">Schnittstellen, Funktionen und Interaktionsaufrufe:</p>\n<ul class=\"fig-list\"><li><code>EthTSyn_MainFunction()</code>: Zyklischer Hauptfunktionsaufruf in Master und Slave.\n</li><li><code>EthTSyn_MainFunction::EthTSyn_MainFunction()</code>: Interner Aufrufkontext auf Masterseite.\n</li><li><code>StbM_BusGetCurrentTime(timeBaseId, &amp;T0, &amp;T0vlt, &amp;userData)</code>: Synchroner Abruf der aktuellen Zeitbasisdaten vom StbM Master durch EthTSyn Master inklusive Rückgabe.\n</li><li><code>EthTSyn_TxConfirmation()</code>: Bestätigungsfunktion des Master-Sendeereignisses.\n</li><li>Interrupt-Service-Routinen: <code>Rx ISR()</code>, <code>Tx Confirmation ISR()</code>.\n</li><li>Protokollnachrichten über Ethernet: <code>Sync Message ()</code>, <code>Followup Message (preciseOriginTimeStamp)</code>.\n</li><li>Zeitvalidierungs-Schnittstellen (StbM):\n<ul class=\"fig-list\"><li><code>StbM_EthSetMasterTimingData(timeBaseId, &amp;measurementData)</code>\n</li><li><code>StbM_EthSetSlaveTiming(timeBaseId, &amp;measurementData)</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Interaktionsreferenzen (<code>ref</code>):</p>\n<ul class=\"fig-list\"><li><code>(INTERNAL) EthTSyn Ingress Time Stamping</code> (auf Slave-Seite)\n</li><li><code>(INTERNAL) EthTSyn Egress Time Stamping</code> (auf Master-Seite)\n</li></ul>\n<p class=\"fig-p\">Datenstrukturen:</p>\n<ul class=\"fig-list\"><li>Master-<code>measurementData</code>: <code>{sequenceId, sourcePortId, syncEgressTimestamp, preciseOriginTimestamp}</code>\n</li><li>Slave-<code>measurementData</code>: <code>{sequenceId, sourcePortId, syncIngressTimestamp, preciseOriginTimestamp, correctionField, pDelay, 0, 0}</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>EthTSyn (Time Master)</code> initiiert im Rahmen der <code>EthTSyn_MainFunction()</code> eine Synchronisationssequenz und ruft via <code>StbM_BusGetCurrentTime(timeBaseId, &amp;T0, &amp;T0vlt, &amp;userData)</code> Zeit- und Statusdaten beim <code>StbM (Time Master)</code> ab.\n</li><li>Der EthTSyn Master sendet eine <code>Sync Message ()</code> über das Netzwerk an den <code>EthTSyn (Time Slave)</code>.\n</li><li>Der Empfang der <code>Sync Message ()</code> löst auf Slave-Seite die <code>Rx ISR()</code> aus, welche die interne Referenzsequenz <code>(INTERNAL) EthTSyn Ingress Time Stamping</code> anstößt.\n</li><li>Auf Master-Seite löst das Senden der Sync-Nachricht die <code>Tx Confirmation ISR()</code> und <code>EthTSyn_TxConfirmation()</code> aus, wodurch <code>(INTERNAL) EthTSyn Egress Time Stamping</code> referenziert wird.\n</li><li>In einem Folgezyklus (<code>EthTSyn_MainFunction::EthTSyn_MainFunction()</code>) des Masters wird, sofern die Option <code>[Time Validation enabled]</code> aktiv ist, die lokale Struktur <code>measurementData</code> befüllt und per synchronem Aufruf <code>StbM_EthSetMasterTimingData(timeBaseId, &amp;measurementData)</code> an den StbM Master übermittelt.\n</li><li>Der EthTSyn Master versendet die <code>Followup Message (preciseOriginTimeStamp)</code> an den EthTSyn Slave.\n</li><li>Der Empfang der Followup-Nachricht stößt im EthTSyn Slave die <code>Rx ISR()</code> und die Referenzsequenz <code>(INTERNAL) EthTSyn Ingress Time Stamping</code> an.\n</li><li>Im nachfolgenden <code>EthTSyn_MainFunction()</code> des Slaves wird die Synchronisationsberechnung abgeschlossen. Ist <code>[Time Validation enabled]</code> aktiv, baut der Slave <code>measurementData</code> auf und ruft <code>StbM_EthSetSlaveTiming(timeBaseId, &amp;measurementData)</code> auf dem StbM Slave auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normativ vorgeschriebene zeitliche Abfolge und Schnittstellenaufrufe für gPTP-basierte Zeitsynchronisation zwischen Time Master und Time Slave über Ethernet. Die Übermittlung von Zeitstempeln und Validierungsdaten an den StbM unterliegt der Bedingung <code>[Time Validation enabled]</code>. Implementierer müssen die korrekte Reihenfolge aus Frame-Übertragung, Timestamp-Erfassung in ISR-/Hardware-Kontexten und anschließender Übergabe der Messwerte an StbM sicherstellen.</p>"}, {"id": "FIG-ec0f5d060236dba6", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Zeitsynchronisation über Ethernet (Time Synchronization Sequence) in der AUTOSAR Classic Platform. Das Diagramm spezifiziert den Interaktionsablauf zwischen den BSW-Modulen Synchronized Time-Base Manager (<code>StbM</code>) und Ethernet Time Synchronization (<code>EthTSyn</code>) jeweils auf Master- und Slave-Seite.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Lebenslinien (Instanzen / Module mit Stereotyp «module»):</p>\n<ul class=\"fig-list\"><li><code>StbM (Time Slave): StbM</code>\n</li><li><code>EthTSyn (Time Slave): EthTSyn</code>\n</li><li><code>EthTSyn (Time Master): EthTSyn</code>\n</li><li><code>StbM (Time Master): StbM</code>\n</li></ul>\n<p class=\"fig-p\">Schnittstellen, Funktionen und Interaktionsaufrufe:</p>\n<ul class=\"fig-list\"><li><code>EthTSyn_MainFunction()</code>: Zyklischer Hauptfunktionsaufruf in Master und Slave.\n</li><li><code>EthTSyn_MainFunction::EthTSyn_MainFunction()</code>: Interner Aufrufkontext auf Masterseite.\n</li><li><code>StbM_BusGetCurrentTime(timeBaseId, &amp;T0, &amp;T0vlt, &amp;userData)</code>: Synchroner Abruf der aktuellen Zeitbasisdaten vom StbM Master durch EthTSyn Master inklusive Rückgabe.\n</li><li><code>EthTSyn_TxConfirmation()</code>: Bestätigungsfunktion des Master-Sendeereignisses.\n</li><li>Interrupt-Service-Routinen: <code>Rx ISR()</code>, <code>Tx Confirmation ISR()</code>.\n</li><li>Protokollnachrichten über Ethernet: <code>Sync Message ()</code>, <code>Followup Message (preciseOriginTimeStamp)</code>.\n</li><li>Zeitvalidierungs-Schnittstellen (StbM):\n<ul class=\"fig-list\"><li><code>StbM_EthSetMasterTimingData(timeBaseId, &amp;measurementData)</code>\n</li><li><code>StbM_EthSetSlaveTimingData(timeBaseId, &amp;measurementData)</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Interaktionsreferenzen (<code>ref</code>):</p>\n<ul class=\"fig-list\"><li><code>(INTERNAL) EthTSyn Ingress Time Stamping</code> (auf Slave-Seite)\n</li><li><code>(INTERNAL) EthTSyn Egress Time Stamping</code> (auf Master-Seite)\n</li></ul>\n<p class=\"fig-p\">Datenstrukturen:</p>\n<ul class=\"fig-list\"><li>Master-<code>measurementData</code>: <code>{sequenceId, sourcePortId, syncEgressTimestamp, preciseOriginTimestamp}</code>\n</li><li>Slave-<code>measurementData</code>: <code>{sequenceId, sourcePortId, syncIngressTimestamp, preciseOriginTimestamp, correctionField, pDelay, 0, 0}</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>EthTSyn (Time Master)</code> initiiert im Rahmen der <code>EthTSyn_MainFunction()</code> eine Synchronisationssequenz und ruft via <code>StbM_BusGetCurrentTime(timeBaseId, &amp;T0, &amp;T0vlt, &amp;userData)</code> Zeit- und Statusdaten beim <code>StbM (Time Master)</code> ab.\n</li><li>Der EthTSyn Master sendet eine <code>Sync Message ()</code> über das Netzwerk an den <code>EthTSyn (Time Slave)</code>.\n</li><li>Der Empfang der <code>Sync Message ()</code> löst auf Slave-Seite die <code>Rx ISR()</code> aus, welche die interne Referenzsequenz <code>(INTERNAL) EthTSyn Ingress Time Stamping</code> anstößt.\n</li><li>Auf Master-Seite löst das Senden der Sync-Nachricht die <code>Tx Confirmation ISR()</code> und <code>EthTSyn_TxConfirmation()</code> aus, wodurch <code>(INTERNAL) EthTSyn Egress Time Stamping</code> referenziert wird.\n</li><li>In einem Folgezyklus (<code>EthTSyn_MainFunction::EthTSyn_MainFunction()</code>) des Masters wird, sofern die Option <code>[Time Validation enabled]</code> aktiv ist, die lokale Struktur <code>measurementData</code> befüllt und per synchronem Aufruf <code>StbM_EthSetMasterTimingData(timeBaseId, &amp;measurementData)</code> an den StbM Master übermittelt.\n</li><li>Der EthTSyn Master versendet die <code>Followup Message (preciseOriginTimeStamp)</code> an den EthTSyn Slave.\n</li><li>Der Empfang der Followup-Nachricht stößt im EthTSyn Slave die <code>Rx ISR()</code> und die Referenzsequenz <code>(INTERNAL) EthTSyn Ingress Time Stamping</code> an.\n</li><li>Im nachfolgenden <code>EthTSyn_MainFunction()</code> des Slaves wird die Synchronisationsberechnung abgeschlossen. Ist <code>[Time Validation enabled]</code> aktiv, baut der Slave <code>measurementData</code> auf und ruft <code>StbM_EthSetSlaveTimingData(timeBaseId, &amp;measurementData)</code> auf dem StbM Slave auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normativ vorgeschriebene zeitliche Abfolge und Schnittstellenaufrufe für gPTP-basierte Zeitsynchronisation zwischen Time Master und Time Slave über Ethernet. Die Übermittlung von Zeitstempeln und Validierungsdaten an den StbM unterliegt der Bedingung <code>[Time Validation enabled]</code>. Implementierer müssen die korrekte Reihenfolge aus Frame-Übertragung, Timestamp-Erfassung in ISR-/Hardware-Kontexten und anschließender Übergabe der Messwerte an StbM sicherstellen.</p>"}], "trans": [{"from": "FIG-25c6b4fabf7e339d", "to": "FIG-ec0f5d060236dba6", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Aufruf an StbM Time Slave bei aktivierter Time Validation umbenannt: <code>StbM_EthSetSlaveTiming(timeBaseId, &amp;measurementData)</code> geändert zu <code>StbM_EthSetSlaveTimingData(timeBaseId, &amp;measurementData)</code>.\n</li><li>Diagrammrahmen und Kopfzeile <code>sd EthTSyn_TimesyncSequence</code> entfernt.\n</li></ul>"}]};
